package server

import "html/template"

func portalLayoutClass(files, users, chat bool) string {
	if chat {
		if users {
			return "layout-chat-users"
		}
		return "layout-chat-only"
	}
	if files {
		return "layout-files-only"
	}
	return "layout-empty"
}

